    {
      "id": "TavernChoice",
      "text": "Approach the hooded stranger.",
      "speaker": "",
      "type": "choice"
    },
    {
      "id": "ObserveRoom",
      "text": "You notice the stranger slipping a note to the barkeep. The merchant counts gold nervously.",
      "speaker": "Narrator",
      "type": "line"
    },
    {
      "id": "ObserveChoice",
      "text": "Intercept the note.",
      "speaker": "",
      "type": "choice"
    },
    {
      "id": "InterceptNote",
      "text": "You dare?!",
      "speaker": "Stranger",
      "type": "line"
    },
    {
      "id": "PickpocketAttempt",
      "text": "[Sleight of Hand] Swiftly grab the pouch.",
      "speaker": "",
      "type": "choice"
    },
    {
      "id": "PickpocketSuccess",
      "text": "50 gold pieces heavier, you slip away. The merchant hasn't noticed... yet.",
      "speaker": "Narrator",
      "type": "line"
    },

